/* Generated by `helix family machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type ValidationContext, type ValidationInput, customize, fails, forget, fresh, judge, passes, shows, showsCustomized, showsJudged, showsOnReset, showsOnTouch, touch } from './machine.js'

export type { ValidationContext, ValidationInput } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'validation'

/** The state `invalid`. */
export const STATE_INVALID = 0
/** The state `touched`. */
export const STATE_TOUCHED = 1
/** The state `untouched`. */
export const STATE_UNTOUCHED = 2
/** Each state's name, by its number. */
export const STATES = ['invalid', 'touched', 'untouched'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['invalid', 'touched', 'untouched'] as const

/** The event `JUDGE`. */
export const EVENT_JUDGE = 0
/** The event `CUSTOM`. */
export const EVENT_CUSTOM = 1
/** The event `TOUCH`. */
export const EVENT_TOUCH = 2
/** The event `CHECK`. */
export const EVENT_CHECK = 3
/** The event `REPORT`. */
export const EVENT_REPORT = 4
/** The event `RESET`. */
export const EVENT_RESET = 5
/** Each event's name, by its number. */
export const EVENTS = ['JUDGE', 'CUSTOM', 'TOUCH', 'CHECK', 'REPORT', 'RESET'] as const

/** The effect `apply`. */
export const EFFECT_APPLY = 0
/** The effect `announce`. */
export const EFFECT_ANNOUNCE = 1
/** The effect `point`. */
export const EFFECT_POINT = 2
/** Each effect's name, by its number. */
export const EFFECTS = ['apply', 'announce', 'point'] as const

/** Each request event's name, by its number. */
export const ASKS = [] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: ValidationContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: ValidationContext): number =>
  shows(context) ? STATE_INVALID : fresh(context) ? STATE_UNTOUCHED : STATE_TOUCHED

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (_state: number): readonly Effect[] => []

/** What `invalid` does with each event. */
const inInvalid = (context: ValidationContext, event: number, input: ValidationInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_JUDGE:
      return showsJudged(context, input) ? { context: judge(context, input), effects: [[EFFECT_APPLY]], state: STATE_INVALID } : fresh(context) ? { context: judge(context, input), effects: [[EFFECT_APPLY]], state: STATE_UNTOUCHED } : { context: judge(context, input), effects: [[EFFECT_APPLY]], state: STATE_TOUCHED }
    case EVENT_CUSTOM:
      return showsCustomized(context, input) ? { context: customize(context, input), effects: [[EFFECT_APPLY]], state: STATE_INVALID } : fresh(context) ? { context: customize(context, input), effects: [[EFFECT_APPLY]], state: STATE_UNTOUCHED } : { context: customize(context, input), effects: [[EFFECT_APPLY]], state: STATE_TOUCHED }
    case EVENT_TOUCH:
      return { context: touch(context), effects: [], state: STATE_INVALID }
    case EVENT_CHECK:
      return fails(context) ? { context: context, effects: [[EFFECT_ANNOUNCE]], state: STATE_INVALID } : undefined
    case EVENT_REPORT:
      return passes(context) ? { context: context, effects: [[EFFECT_APPLY]], state: STATE_INVALID } : { context: touch(context), effects: [[EFFECT_APPLY], [EFFECT_ANNOUNCE], [EFFECT_POINT]], state: STATE_INVALID }
    case EVENT_RESET:
      return showsOnReset(context) ? { context: forget(context), effects: [], state: STATE_INVALID } : { context: forget(context), effects: [], state: STATE_UNTOUCHED }
  }
  return undefined
}

/** What `touched` does with each event. */
const inTouched = (context: ValidationContext, event: number, input: ValidationInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_JUDGE:
      return showsJudged(context, input) ? { context: judge(context, input), effects: [[EFFECT_APPLY]], state: STATE_INVALID } : { context: judge(context, input), effects: [[EFFECT_APPLY]], state: STATE_TOUCHED }
    case EVENT_CUSTOM:
      return showsCustomized(context, input) ? { context: customize(context, input), effects: [[EFFECT_APPLY]], state: STATE_INVALID } : { context: customize(context, input), effects: [[EFFECT_APPLY]], state: STATE_TOUCHED }
    case EVENT_CHECK:
      return fails(context) ? { context: context, effects: [[EFFECT_ANNOUNCE]], state: STATE_TOUCHED } : undefined
    case EVENT_REPORT:
      return passes(context) ? { context: context, effects: [[EFFECT_APPLY]], state: STATE_TOUCHED } : { context: touch(context), effects: [[EFFECT_APPLY], [EFFECT_ANNOUNCE], [EFFECT_POINT]], state: STATE_TOUCHED }
    case EVENT_RESET:
      return { context: forget(context), effects: [], state: STATE_UNTOUCHED }
  }
  return undefined
}

/** What `untouched` does with each event. */
const inUntouched = (context: ValidationContext, event: number, input: ValidationInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_JUDGE:
      return showsJudged(context, input) ? { context: judge(context, input), effects: [[EFFECT_APPLY]], state: STATE_INVALID } : { context: judge(context, input), effects: [[EFFECT_APPLY]], state: STATE_UNTOUCHED }
    case EVENT_CUSTOM:
      return showsCustomized(context, input) ? { context: customize(context, input), effects: [[EFFECT_APPLY]], state: STATE_INVALID } : { context: customize(context, input), effects: [[EFFECT_APPLY]], state: STATE_UNTOUCHED }
    case EVENT_TOUCH:
      return showsOnTouch(context) ? { context: touch(context), effects: [], state: STATE_INVALID } : { context: touch(context), effects: [], state: STATE_TOUCHED }
    case EVENT_CHECK:
      return fails(context) ? { context: context, effects: [[EFFECT_ANNOUNCE]], state: STATE_UNTOUCHED } : undefined
    case EVENT_REPORT:
      return passes(context) ? { context: context, effects: [[EFFECT_APPLY]], state: STATE_UNTOUCHED } : showsOnTouch(context) ? { context: touch(context), effects: [[EFFECT_APPLY], [EFFECT_ANNOUNCE], [EFFECT_POINT]], state: STATE_INVALID } : { context: touch(context), effects: [[EFFECT_APPLY], [EFFECT_ANNOUNCE], [EFFECT_POINT]], state: STATE_TOUCHED }
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: ValidationContext, event: number, input: ValidationInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_INVALID:
      return inInvalid(context, event, input)
    case STATE_TOUCHED:
      return inTouched(context, event, input)
    case STATE_UNTOUCHED:
      return inUntouched(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (_state: number, _context: ValidationContext, _owner: number): Move | undefined =>
  undefined

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: ValidationContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (state: number): readonly string[] => {
  switch (state) {
    case STATE_INVALID:
      return ['invalid']
  }
  return []
}
